CREATE TABLE official_response(id uuid PRIMARY KEY,source_id text NOT NULL REFERENCES source_registry(id),job_id uuid NOT NULL REFERENCES ingestion_job(id),url text NOT NULL,response_status integer NOT NULL CHECK(response_status=200),raw_content bytea NOT NULL,sha256 char(64) NOT NULL CHECK(sha256=encode(sha256(raw_content),'hex')),acquired_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE response_evidence(response_id uuid REFERENCES official_response(id),evidence_id uuid REFERENCES raw_evidence(id),section text NOT NULL DEFAULT '',PRIMARY KEY(response_id,evidence_id,section));
CREATE TABLE macro_series(id text PRIMARY KEY,source_id text NOT NULL REFERENCES source_registry(id),flow text NOT NULL,series_key text NOT NULL,title text NOT NULL,units text NOT NULL,frequency text NOT NULL,currency text,currency_denominator text,metadata jsonb NOT NULL,response_id uuid NOT NULL REFERENCES official_response(id),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,flow,series_key));
CREATE TABLE macro_observation(evidence_id uuid PRIMARY KEY REFERENCES raw_evidence(id),series_id text NOT NULL REFERENCES macro_series(id),observation_date date NOT NULL,value numeric,observation_status text NOT NULL,version integer NOT NULL CHECK(version>0),UNIQUE(series_id,observation_date,version));
CREATE INDEX macro_latest ON macro_observation(series_id,observation_date DESC,version DESC);
CREATE TABLE event_candidate(event_id uuid PRIMARY KEY REFERENCES financial_event(id),evidence_id uuid NOT NULL REFERENCES raw_evidence(id),rule_version text NOT NULL,topics jsonb NOT NULL,score integer NOT NULL CHECK(score BETWEEN 0 AND 100),score_basis jsonb NOT NULL,cluster_key char(64) NOT NULL,cluster_basis text NOT NULL,source_host text,verification text NOT NULL DEFAULT 'PENDING' CHECK(verification IN('PENDING','CONFLICT','VERIFIED','REJECTED')),processed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX candidate_ranking ON event_candidate(score DESC,event_id);
CREATE INDEX candidate_clusters ON event_candidate(cluster_key);
CREATE TABLE financial_entity(id uuid PRIMARY KEY,type text NOT NULL CHECK(type IN('COUNTRY','REGION','CENTRAL_BANK','REGULATOR','ORGANIZATION','COMPANY','SECURITY','INDEX','COMMODITY','CURRENCY','INDUSTRY','SECTOR','INDICATOR')),official_name text NOT NULL,identity_key text NOT NULL,english_name text,chinese_name text,source_id text NOT NULL REFERENCES source_registry(id),source_url text NOT NULL,evidence_id uuid NOT NULL REFERENCES raw_evidence(id),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','VERIFIED','CONFLICT','EXPIRED')),valid_from timestamptz,valid_until timestamptz,UNIQUE(type,source_id,identity_key));
CREATE TABLE entity_identifier(id bigserial PRIMARY KEY,entity_id uuid NOT NULL REFERENCES financial_entity(id),kind text NOT NULL,value text NOT NULL,market text NOT NULL DEFAULT '',valid_from timestamptz,valid_until timestamptz,evidence_id uuid NOT NULL REFERENCES raw_evidence(id),UNIQUE(entity_id,kind,value,market));
CREATE TABLE entity_alias(entity_id uuid REFERENCES financial_entity(id),alias text NOT NULL,evidence_id uuid NOT NULL REFERENCES raw_evidence(id),PRIMARY KEY(entity_id,alias));
CREATE TABLE event_entity(event_id uuid REFERENCES financial_event(id),entity_id uuid REFERENCES financial_entity(id),evidence_id uuid NOT NULL REFERENCES raw_evidence(id),match_basis text NOT NULL,status text NOT NULL DEFAULT 'PENDING',PRIMARY KEY(event_id,entity_id));
CREATE TABLE entity_relation(id uuid PRIMARY KEY,subject_id uuid NOT NULL REFERENCES financial_entity(id),object_id uuid NOT NULL REFERENCES financial_entity(id),type text NOT NULL CHECK(type IN('ISSUER','LISTED','INDUSTRY','BUSINESS','CUSTOMER','SUPPLIER','COMPETITOR','EQUITY','MATERIAL_DEPENDENCY','MACRO_SENSITIVITY','TRANSMISSION')),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','VERIFIED','EXPIRED','CONFLICT','REJECTED')),evidence_id uuid REFERENCES raw_evidence(id),first_public_at timestamptz,effective_from timestamptz,effective_until timestamptz,disclosed_at timestamptz,explanation text NOT NULL,CHECK(subject_id<>object_id),CHECK(status<>'VERIFIED' OR (evidence_id IS NOT NULL AND first_public_at IS NOT NULL AND disclosed_at IS NOT NULL)));
CREATE TABLE research_review(id bigserial PRIMARY KEY,target_type text NOT NULL,target_id uuid NOT NULL,actor text NOT NULL,decision text NOT NULL,reason text NOT NULL,evidence_id uuid REFERENCES raw_evidence(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE candidate_official_evidence(event_id uuid REFERENCES financial_event(id),evidence_id uuid REFERENCES raw_evidence(id),status text NOT NULL DEFAULT 'PENDING',reason text NOT NULL,PRIMARY KEY(event_id,evidence_id));
CREATE FUNCTION research_verified_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.status='VERIFIED' AND NOT EXISTS(SELECT 1 FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id WHERE r.id=NEW.evidence_id AND s.level='L0' AND r.raw_content_hash=encode(sha256(r.raw_content),'hex')) THEN RAISE EXCEPTION 'Verified research requires intact official evidence'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER entity_verified_guard BEFORE INSERT OR UPDATE ON financial_entity FOR EACH ROW EXECUTE FUNCTION research_verified_guard();
CREATE TRIGGER relation_verified_guard BEFORE INSERT OR UPDATE ON entity_relation FOR EACH ROW EXECUTE FUNCTION research_verified_guard();
